def refinementVariation (B : Lp ℝ 1 haar →L[ℝ] Lp ℝ 1 haar) (S T : Finset ℕ) : ℝ :=
  finiteAverage (fun ab : Assignments S × Assignments T =>
    ‖B (kernelL1 (S ∪ T) (merge S T ab.1 ab.2)) - B (kernelL1 S (extend S ab.1))‖)

